(async () => {
  const fs = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  try { await fs.promises.access(inputPath); } catch { throw new Error('Input file not found'); }
  const csv = await fs.promises.readFile(inputPath, 'utf8');
  globalThis._csvContent = csv;
  globalThis._outputPath = outputPath;
})();

(async () => {
  const { default: Papa } = await import('papaparse');
  const csv = globalThis._csvContent;
  const outputPath = globalThis._outputPath;
  const result = Papa.parse(csv, { header: true, skipEmptyLines: true });
  if (result.errors && result.errors.length) {
    throw new Error('Parse errors: ' + JSON.stringify(result.errors));
  }
  const jsonStr = JSON.stringify(result.data, null, 2);
  const fs = await import('node:fs');
  await fs.promises.writeFile(outputPath, jsonStr, 'utf8');
  globalThis._jsonPath = outputPath;
})();
